package net.officefloor.hq.app.opening;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.ResultSet;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.Map;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The opening balances pasted onto each sheet: amounts added to a person's carried figure for a period. */
@Repository
public class OpeningRepository {

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public OpeningRepository(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** Stores one opening amount for the person and period, made on the sheet's today. */
    public void add(String sheetId, long periodId, long personId, BigDecimal amount) {
        jdbc.update("INSERT INTO opening (sheet_id, period_id, person_id, amount, made_on) VALUES (?, ?, ?, ?, ?)",
                sheetId, periodId, personId, amount, Date.valueOf(sheets.today(sheetId)));
    }

    /** Each person's opening amounts for the period added up, by person id: as of a date (see AsOf) only those made
     *  while the sheet's today was on or before it; null for all of them. */
    public Map<Long, BigDecimal> totals(Period period, LocalDate asOf) {
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        jdbc.query("SELECT person_id, amount, made_on FROM opening WHERE sheet_id = ? AND period_id = ? ORDER BY id",
                (ResultSet rs) -> {
                    if (asOf == null || AsOf.counts(rs.getObject("made_on", LocalDate.class), asOf)) {
                        totals.merge(rs.getLong("person_id"), rs.getBigDecimal("amount").setScale(2), BigDecimal::add);
                    }
                }, period.sheetId(), period.id());
        return totals;
    }
}
